/* Quiz-spørsmål.
   Skjema (flervalg):  { id, topic, type:"mc", q, options:[...], correct:<index>, explain }
   Skjema (åpent):     { id, topic, type:"open", q, model:"<html>" }
   Utvid: legg til flere objekter. topic må matche en id i TOPICS. */
window.APP_DATA = window.APP_DATA || {};
window.APP_DATA.quizzes = [

/* ===================== METODIKK & AGILE ===================== */
{ id:"me1", topic:"metodikk", type:"mc", q:"Hva vektlegger Det smidige manifestet mest?", options:["Omfattende dokumentasjon over fungerende programvare","Fungerende programvare over dokumentasjon","Å følge en plan over å respondere på endring","Kontraktsforhandling over kundesamarbeid"], correct:1, explain:"Manifestet verdsetter fungerende programvare, individer/samspill, kundesamarbeid og respons på endring høyest – men begge sider har verdi." },
{ id:"me2", topic:"metodikk", type:"mc", q:"Hvem prioriterer Product Backlog i Scrum?", options:["Scrum Master","Utviklingsteamet","Product Owner","Kunden direkte"], correct:2, explain:"Product Owner eier og prioriterer backloggen ut fra forretningsverdi." },
{ id:"me3", topic:"metodikk", type:"mc", q:"Hvor lang er en daglig standup (daily scrum) typisk?", options:["5 minutter","15 minutter","30–60 minutter","Én hel time"], correct:1, explain:"Time-boxet til ca. 15 minutter: hva gjorde jeg, hva skal jeg gjøre, hindringer." },
{ id:"me4", topic:"metodikk", type:"mc", q:"Hva er hensikten med en WIP-grense (work in progress) i Kanban?", options:["Å øke antall oppgaver per person samtidig","Å begrense samtidig arbeid (WIP)","Å fjerne behovet for testing helt","Å erstatte sprintplanlegging i Scrum"], correct:1, explain:"WIP-grenser hindrer overbelastning og synliggjør flaskehalser i flyten." },
{ id:"me5", topic:"metodikk", type:"mc", q:"Hva er riktig rekkefølge i TDD-syklusen?", options:["Refactor → Red → Green","Green → Red → Refactor","Red → Green → Refactor","Red → Refactor → Green"], correct:2, explain:"Skriv en test som feiler (Red), minimal kode som passerer (Green), rydd opp (Refactor)." },
{ id:"me6", topic:"metodikk", type:"mc", q:"Hva er den største ulempen med fossefallsmodellen?", options:["For mye kundekontakt underveis","For lite dokumentasjon","Sene endringer blir veldig dyre å rette","For korte iterasjoner til å rekke alt"], correct:2, explain:"Den sekvensielle strukturen gjør sene endringer kostbare; kunden ser produktet sent." },
{ id:"me7", topic:"metodikk", type:"mc", q:"Hva er en typisk sprintlengde i Scrum?", options:["Noen timer","1–4 uker","3–6 måneder","Ett år"], correct:1, explain:"Sprinter er korte, faste tidsbokser, vanligvis 1–4 uker." },
{ id:"me8", topic:"metodikk", type:"open", q:"Sammenlign fossefall og smidig utvikling. Nevn én styrke ved hver.", model:"<strong>Fossefall:</strong> sekvensiell, mye planlegging/dokumentasjon på forhånd. Styrke: forutsigbart og oversiktlig for stabile, godt forståtte krav.<br><strong>Smidig:</strong> iterativt og inkrementelt, hyppige leveranser og tilbakemelding. Styrke: håndterer endring godt og reduserer risiko ved å levere verdi tidlig. Velg ut fra hvor stabile kravene er." },
{ id:"me9", topic:"metodikk", type:"open", q:"Forklar de fire Scrum-seremoniene og hva de er til for.", model:"<strong>Sprint Planning:</strong> velger og planlegger hva som skal gjøres i sprinten.<br><strong>Daily Standup:</strong> kort daglig synkronisering, avdekker hindringer.<br><strong>Sprint Review:</strong> demonstrerer inkrementet for interessenter og får tilbakemelding.<br><strong>Retrospektiv:</strong> teamet forbedrer sin egen arbeidsmåte." },
{ id:"me10", topic:"metodikk", type:"mc", q:"Hvilket er et kjerneprinsipp i Lean software development?", options:["Maksimer dokumentasjon","Eliminer sløsing (waste)","Unngå tilbakemelding fra kunden","Frys kravene tidlig"], correct:1, explain:"Lean handler om å eliminere sløsing og optimalisere helheten ('think big, act small, fail fast')." },
{ id:"me11", topic:"metodikk", type:"mc", q:"Hvilken praksis hører til Extreme Programming (XP)?", options:["Big design up front","Parprogrammering","Kun manuell testing","Årlige leveranser"], correct:1, explain:"XP omfatter parprogrammering, TDD, kontinuerlig integrasjon og refaktorering." },
{ id:"me12", topic:"metodikk", type:"mc", q:"Hva er Scrum Masterens hovedrolle?", options:["Bestemme alle tekniske løsninger for teamet","Prioritere og eie produktkravene","Fjerne hindringer og fasilitere teamet","Skrive mesteparten av koden"], correct:2, explain:"Scrum Master er en tjenende leder som fasiliterer Scrum og rydder hindringer." },
{ id:"me13", topic:"metodikk", type:"mc", q:"Hvilket av disse er IKKE et Scrum-artefakt?", options:["Product Backlog","Sprint Backlog","Inkrement","Gantt-diagram"], correct:3, explain:"De tre artefaktene er Product Backlog, Sprint Backlog og Inkrement." },
{ id:"me14", topic:"metodikk", type:"open", q:"Når kan Kanban passe bedre enn Scrum?", model:"Kanban passer der arbeidet er mer kontinuerlig og uforutsigbart, f.eks. drift/support med stadig innkomne oppgaver, eller når man vil unngå faste sprinter. Den gir fleksibel prioritering, fokus på flyt og WIP-grenser fremfor tidsbokset planlegging." },
{ id:"me15", topic:"metodikk", type:"mc", q:"Hva er riktig rekkefølge på fasene i Unified Process (UP)?", options:["Inception → Elaboration → Construction → Transition","Construction → Inception → Transition → Elaboration","Elaboration → Inception → Construction → Transition","Transition → Construction → Elaboration → Inception"], correct:0, explain:"UP går Inception → Elaboration → Construction → Transition, iterativt." },
{ id:"me16", topic:"metodikk", type:"mc", q:"Hva er hovedformålet med et sprint-retrospektiv?", options:["Demonstrere produktet for kunden og eierne","Planlegge neste sprint i detalj","Forbedre teamets egen arbeidsmåte","Estimere hele backloggen på nytt"], correct:2, explain:"Retrospektivet ser på prosessen: hva gikk bra, hva kan forbedres." },

/* ===================== TESTING ===================== */
{ id:"te1", topic:"testing", type:"mc", q:"Hva tester en enhetstest (unit test)?", options:["Hele systemet ende-til-ende","Én isolert komponent/enhet","Samspillet mellom flere moduler","Brukernes tilfredshet"], correct:1, explain:"Enhetstester sjekker én isolert enhet (f.eks. en metode/klasse)." },
{ id:"te2", topic:"testing", type:"mc", q:"Hva kjennetegner black-box-testing?", options:["Man tester ut fra den interne kodestrukturen og logikken","Man tester mot spesifikasjonen uten å se koden","Man måler hvor mye av koden som kjøres","Man tester kun ytelse og hastighet"], correct:1, explain:"Black-box ser bort fra implementasjonen og tester input/forventet output." },
{ id:"te3", topic:"testing", type:"mc", q:"Grendekning (branch coverage) er et eksempel på …", options:["Black-box-testing","White-box-testing","Akseptansetesting","Brukervennlighetstesting"], correct:1, explain:"Dekningsmål basert på kodestruktur er white-box." },
{ id:"te4", topic:"testing", type:"mc", q:"Hva skiller BDD fra TDD?", options:["BDD beskriver oppførsel i et felles språk","BDD bruker ingen automatiske tester i det hele tatt","TDD krever ingen kode for å fungere","De er nøyaktig det samme"], correct:0, explain:"BDD fokuserer på oppførsel/forretningsverdi i et felles språk; TDD er mer teknisk enhetsnært." },
{ id:"te5", topic:"testing", type:"mc", q:"Hva er hensikten med regresjonstesting?", options:["Teste at ny funksjonalitet er rask nok","Sikre at endringer ikke ødela noe gammelt","Teste brukergrensesnittets estetikk og farger","Erstatte alle enhetstestene"], correct:1, explain:"Regresjonstester fanger opp at nye endringer ikke bryter eksisterende funksjonalitet." },
{ id:"te6", topic:"testing", type:"mc", q:"Hva ligger nederst (flest tester) i testpyramiden?", options:["Ende-til-ende-tester","Manuelle tester","Enhetstester","Akseptansetester"], correct:2, explain:"Mange raske, billige enhetstester nederst; færre dyre ende-til-ende øverst." },
{ id:"te7", topic:"testing", type:"mc", q:"Hvem utfører/godkjenner typisk en akseptansetest?", options:["Kompilatoren automatisk under bygging","Kunden/sluttbruker mot kravene","Kun den enkelte utvikleren","Databasen automatisk"], correct:1, explain:"Akseptansetest verifiserer at systemet oppfyller kundens krav, ofte med kunden involvert." },
{ id:"te8", topic:"testing", type:"open", q:"Forklar forskjellen på enhetstesting og integrasjonstesting.", model:"<strong>Enhetstest:</strong> tester én isolert komponent, ofte med mock/stub for avhengigheter – raskt og presist på feil-lokalisering.<br><strong>Integrasjonstest:</strong> tester at flere komponenter fungerer sammen (f.eks. tjeneste + database) – fanger feil i grensesnittene mellom dem." },
{ id:"te9", topic:"testing", type:"open", q:"Nevn én fordel og én utfordring med TDD.", model:"<strong>Fordel:</strong> gir et sikkerhetsnett som gjør refaktorering trygg, og driver fram testbar, modulær design.<br><strong>Utfordring:</strong> krever disiplin og kan kjennes treigt i starten; tester må vedlikeholdes, og dårlig skrevne tester kan bli skjøre." },
{ id:"te10", topic:"testing", type:"mc", q:"Hva er kontinuerlig integrasjon (CI)?", options:["Å integrere nye teammedlemmer i prosjektet jevnlig","Automatisk bygg og test ved hver endring","Å skrive all koden helt på slutten","Manuell testing én gang i måneden"], correct:1, explain:"CI bygger og kjører tester automatisk ved hver innsjekk, og gir rask tilbakemelding." },
{ id:"te11", topic:"testing", type:"mc", q:"Hvilken testtype sjekker oppførsel under høy belastning?", options:["Røyktest (smoke test)","Stress-/lasttest","Enhetstest","Regresjonstest"], correct:1, explain:"Stress-/lasttest måler ytelse og stabilitet under belastning." },
{ id:"te12", topic:"testing", type:"mc", q:"Hva er det viktigste elementet i en god feilrapport (bug report)?", options:["Navnet på utvikleren bak feilen","Tydelige steg for å reprodusere feilen","Hvilke farger UI-et bruker","Antall linjer kode i filen"], correct:1, explain:"Reproduserbare steg + forventet vs. faktisk resultat er kjernen i en nyttig bug-rapport." },
{ id:"te13", topic:"testing", type:"mc", q:"Hva er en røyktest (smoke test)?", options:["En test av sikkerhet mot ondsinnede angrep","Rask sjekk av at hovedfunksjonene faktisk virker","En full og grundig regresjonstest","En test med ekte sluttbrukere"], correct:1, explain:"Smoke-test verifiserer raskt at byggets kjernefunksjoner fungerer før videre testing." },
{ id:"te14", topic:"testing", type:"open", q:"Når bør man automatisere tester, og når passer manuell testing best?", model:"<strong>Automatiser</strong> repeterbare, deterministiske tester som kjøres ofte (enhets-, integrasjons- og regresjonstester i CI) – raskt og pålitelig.<br><strong>Manuelt</strong> egner seg til utforskende testing og brukervennlighetstesting, der menneskelig vurdering og kreativitet trengs." },
{ id:"te15", topic:"testing", type:"mc", q:"Hva er brukervennlighetstesting (usability testing)?", options:["Måling av hvor mye av koden som dekkes av tester","Ekte brukere løser oppgaver mens man ser på","Test av databasens ytelse","Test av nettverkets hastighet"], correct:1, explain:"Man observerer reelle brukere som utfører oppgaver for å avdekke brukbarhetsproblemer." },
{ id:"te16", topic:"testing", type:"mc", q:"Hvorfor bør automatiske tester være deterministiske og repeterbare?", options:["For at de skal ta lengst mulig tid å kjøre","Så samme input alltid gir nøyaktig samme resultat","For å slippe å skrive dokumentasjon","For å hindre kontinuerlig integrasjon"], correct:1, explain:"Ustabile (flaky) tester undergraver tilliten; deterministiske tester gir pålitelig tilbakemelding." },

/* ===================== ARKITEKTUR ===================== */
{ id:"ar1", topic:"arkitektur", type:"mc", q:"Hva betyr lav kobling (low coupling)?", options:["Moduler er sterkt avhengige av hverandre","Moduler er lite avhengige av hverandre","All kode i én fil","Ingen moduler i det hele tatt"], correct:1, explain:"Lav kobling gjør moduler lettere å endre og teste uavhengig." },
{ id:"ar2", topic:"arkitektur", type:"mc", q:"Hva betyr høy kohesjon (high cohesion)?", options:["En modul gjør mange helt urelaterte ting","En modul har ett tydelig og samlet ansvar","Mange moduler gjør akkurat det samme","Modulen har ingen klar struktur"], correct:1, explain:"Høy kohesjon = en modul gjør én ting godt; lettere å forstå og vedlikeholde." },
{ id:"ar3", topic:"arkitektur", type:"mc", q:"Hva er riktig rekkefølge i trelagsarkitektur (top→bunn)?", options:["Datalag → Forretningslogikk → Presentasjon (UI)","Presentasjon → Forretningslogikk → Datalag","Logikk → Presentasjon → Datalag","Presentasjon → Datalag → Logikk"], correct:1, explain:"Presentasjon (UI) → forretningslogikk → datalag (persistens)." },
{ id:"ar4", topic:"arkitektur", type:"mc", q:"Hva står M, V og C for i MVC?", options:["Model, View, Controller","Module, Version, Class","Main, View, Core","Model, Variabel, Komponent"], correct:0, explain:"Model (data/logikk), View (visning), Controller (styring)." },
{ id:"ar5", topic:"arkitektur", type:"mc", q:"Hvilken er en fordel med mikrotjenester?", options:["Enklere drift og oppsett enn en monolitt","Tjenester kan skaleres og deployes uavhengig","Ingen nettverkskommunikasjon er nødvendig","Krever ingen CI/CD-pipeline"], correct:1, explain:"Uavhengig skalering/deploy, teknologifrihet og isolerte feil er sentrale fordeler." },
{ id:"ar6", topic:"arkitektur", type:"mc", q:"Hvilken er en ulempe med mikrotjenester?", options:["Vanskelig å skalere enkeltdeler","Økt kompleksitet i drift og nettverk","Kan ikke bruke ulike teknologier samtidig","Tett kobling mellom alle delene"], correct:1, explain:"Distribuert kompleksitet (drift, nettverk, datakonsistens) er den store kostnaden." },
{ id:"ar7", topic:"arkitektur", type:"mc", q:"Hva kjennetegner en monolitt sammenlignet med mikrotjenester?", options:["Mange små, uavhengige tjenester","Én samlet, distribuerbar enhet (alt i én)","Den er alltid skybasert","Den passer kun for små apper"], correct:1, explain:"Monolitten er én enhet – enkel i starten, men tyngre å skalere/endre når den vokser." },
{ id:"ar8", topic:"arkitektur", type:"open", q:"Nevn fire fordeler med en mikrotjenestearkitektur.", model:"1) Uavhengig skalering av enkelttjenester. 2) Uavhengig deploy → raskere leveranser. 3) Teknologifrihet per tjeneste. 4) Isolerte feil (én tjeneste kan feile uten å ta ned alt). 5) Team-autonomi (eier hver sin tjeneste)." },
{ id:"ar9", topic:"arkitektur", type:"open", q:"Hvorfor er det viktig å tenke arkitektur tidlig i prosjektet?", model:"Arkitektur er de grunnleggende beslutningene som er dyre å endre senere. Tidlig arkitekturarbeid reduserer risiko, sikrer at kvalitetskrav (skalerbarhet, sikkerhet, vedlikeholdbarhet) kan oppfylles, og hindrer kostbar omskriving. Maskinvare- og organisasjonshensyn påvirker også valgene." },
{ id:"ar10", topic:"arkitektur", type:"mc", q:"Hva kjennetegner en hendelsesdrevet (event-driven) arkitektur?", options:["Komponenter kaller hverandre direkte og synkront","Komponenter reagerer på hendelser","Alt ligger i ett eneste lag","Ingen kommunikasjon mellom delene"], correct:1, explain:"Produsenter sender hendelser og konsumenter reagerer – gir løs kobling og god skalerbarhet." },
{ id:"ar11", topic:"arkitektur", type:"mc", q:"Hvordan henger SOA og mikrotjenester sammen?", options:["De er direkte motsetninger","SOA er en forløper til mikrotjenester","SOA er en type database","Mikrotjenester kom lenge før SOA i historien"], correct:1, explain:"Begge er tjenesteorienterte; mikrotjenester er en finkornet videreutvikling av SOA-tankegangen." },
{ id:"ar12", topic:"arkitektur", type:"mc", q:"Hva er klient–tjener-modellen?", options:["To likeverdige noder uten faste roller","En klient ber en sentral tjener om tjenester","Alt kjører lokalt uten noe nettverk","Brukes bare til dataspill"], correct:1, explain:"Klienten sender forespørsler; tjeneren leverer ressurser/tjenester." },
{ id:"ar13", topic:"arkitektur", type:"open", q:"Forklar forskjellen på kobling og kohesjon, og hva man bør strebe etter.", model:"<strong>Kobling</strong> = grad av avhengighet mellom moduler. <strong>Kohesjon</strong> = hvor samlet/fokusert ansvaret innad i en modul er. Man bør strebe etter <em>lav kobling</em> (lett å endre/teste) og <em>høy kohesjon</em> (klart ansvar). Dette gir vedlikeholdbar og fleksibel arkitektur." },
{ id:"ar14", topic:"arkitektur", type:"mc", q:"Hvilket mønster skiller visning fra logikk for gjenbrukbart, testbart UI?", options:["Monolitt","MVC","Peer-to-peer","Big ball of mud"], correct:1, explain:"MVC skiller Model/View/Controller slik at UI blir testbart og logikk gjenbrukbar." },

/* ===================== UNIVERSELL UTFORMING ===================== */
{ id:"uu1", topic:"uu", type:"mc", q:"Hva betyr 'Perceivable' (oppfattbar) i WCAG/POUR?", options:["Innhold må kunne sanses","Siden må laste inn raskt nok","Koden må være robust og feilfri overalt","Brukeren må logge inn først"], correct:0, explain:"Perceivable: informasjon må kunne oppfattes – alt-tekst, undertekster, tilstrekkelig kontrast." },
{ id:"uu2", topic:"uu", type:"mc", q:"Hvilke samsvarsnivåer finnes i WCAG?", options:["1, 2, 3","Bronse, Sølv, Gull","A, AA, AAA","Lav, Middels, Høy"], correct:2, explain:"WCAG har nivåene A, AA og AAA." },
{ id:"uu3", topic:"uu", type:"mc", q:"Hvilket WCAG-nivå kreves vanligvis for offentlige nettsteder i Norge?", options:["A","AA","AAA","Ingen krav"], correct:1, explain:"Kravet er nivå AA." },
{ id:"uu4", topic:"uu", type:"mc", q:"Hva illustrerer 'curb-cut effect'?", options:["At tilgjengelighet bare hjelper noen få","At tiltak for noen ofte hjelper alle brukere","At kontrast er helt unødvendig","At lovverk er irrelevant for design"], correct:1, explain:"Tilgjengelighetstiltak (undertekster, ramper, kontrast) gir nytte for langt flere enn målgruppen." },
{ id:"uu5", topic:"uu", type:"mc", q:"Hva er hovedformålet med alt-tekst på bilder?", options:["Å gi bildene bedre kvalitet","At skjermlesere kan formidle bildeinnholdet","Å laste bildene raskere ned fra serveren","Å gjøre layouten penere"], correct:1, explain:"Alt-tekst gjør bildeinnhold oppfattbart for dem som bruker skjermleser." },
{ id:"uu6", topic:"uu", type:"open", q:"Gi tre argumenter for hvorfor universell utforming lønner seg.", model:"1) <strong>Lovkrav</strong> – det er pålagt for IKT mot allmennheten. 2) <strong>Inkludering</strong> – mange har funksjonsnedsettelser og får tilgang. 3) <strong>Bedre for alle + forretning</strong> – klart språk/kontrast hjelper alle brukere, gir større marked og bedre søkemotorsynlighet (SEO)." },
{ id:"uu7", topic:"uu", type:"mc", q:"Hvilket er ett av de 7 prinsippene for universell utforming?", options:["Maksimal fysisk anstrengelse","Toleranse for feil","Skjult informasjon","Kun for eksperter"], correct:1, explain:"De sju prinsippene inkluderer bl.a. 'toleranse for feil' og 'enkel og intuitiv bruk'." },
{ id:"uu8", topic:"uu", type:"mc", q:"At alt kan betjenes med tastatur hører under hvilket POUR-prinsipp?", options:["Perceivable","Operable","Understandable","Robust"], correct:1, explain:"Operable (betjenbar) krever bl.a. full tastaturnavigasjon." },
{ id:"uu9", topic:"uu", type:"open", q:"Nevn fire konkrete tiltak for bedre tilgjengelighet på et nettsted.", model:"Tilstrekkelig fargekontrast; alt-tekst på bilder; full tastaturnavigasjon og synlig fokus; semantisk HTML/ARIA for skjermlesere; undertekster på video; klart språk og tydelige feilmeldinger." },
{ id:"uu10", topic:"uu", type:"mc", q:"Hvem har nytte av universell utforming?", options:["Bare blinde og svaksynte brukere","Bare eldre mennesker","Alle brukere i ulike situasjoner","Bare utviklere og testere"], correct:2, explain:"UU gir gevinster for alle (situasjonsbestemte begrensninger, midlertidige skader, ulike enheter)." },

/* ===================== ETIKK & GDPR ===================== */
{ id:"et1", topic:"etikk", type:"mc", q:"Hva innebærer prinsippet om dataminimering i GDPR?", options:["Samle inn så mye data som overhodet mulig","Samle bare nødvendige data","Aldri slette innsamlet data","Dele data fritt med andre"], correct:1, explain:"Dataminimering: bare nødvendige personopplysninger skal samles inn og behandles." },
{ id:"et2", topic:"etikk", type:"mc", q:"Hva betyr formålsbegrensning?", options:["Data kan brukes til hva som helst senere","Data brukes kun til det oppgitte formålet","Data må alltid krypteres","Data skal aldri lagres noe sted"], correct:1, explain:"Formålsbegrensning: innsamlet data brukes kun til det formålet det ble samlet inn for." },
{ id:"et3", topic:"etikk", type:"mc", q:"Hvilken rettighet kalles ofte 'retten til å bli glemt'?", options:["Rett til innsyn","Rett til sletting av egne data","Rett til dataportabilitet","Rett til retting"], correct:1, explain:"Retten til sletting lar den registrerte få fjernet sine personopplysninger under visse vilkår." },
{ id:"et4", topic:"etikk", type:"mc", q:"Når kreves en DPIA (personvernkonsekvensvurdering)?", options:["Alltid, ved absolutt enhver behandling av data","Når behandlingen gir høy personvernrisiko","Aldri – det er frivillig","Kun i offentlig sektor"], correct:1, explain:"DPIA kreves ved sannsynlig høy risiko, f.eks. omfattende profilering eller sensitive data." },
{ id:"et5", topic:"etikk", type:"mc", q:"Hva er et gyldig behandlingsgrunnlag i GDPR?", options:["Ren nysgjerrighet hos firmaet","Samtykke, avtale eller lovkrav","At det er praktisk for firmaet å ha dem","At dataene allerede finnes"], correct:1, explain:"Behandling krever et grunnlag som samtykke, avtale, rettslig forpliktelse, vitale/allmenne interesser eller berettiget interesse." },
{ id:"et6", topic:"etikk", type:"open", q:"En app samler inn nøyaktig posisjon hele døgnet selv om den bare trenger by-nivå ved bruk. Hvilke GDPR-prinsipper brytes, og hva bør gjøres?", model:"Brudd på <strong>dataminimering</strong> (samler mer enn nødvendig) og <strong>formålsbegrensning</strong> (kontinuerlig sporing utover formålet). Tiltak: samle kun grov posisjon, kun ved aktiv bruk; innhent gyldig samtykke; vær åpen om bruken (åpenhet); sett lagringsbegrensning og slett når formålet er nådd." },
{ id:"et7", topic:"etikk", type:"mc", q:"Hva betyr ansvarlighet (accountability) i GDPR?", options:["At det alltid er brukeren selv som har ansvaret","Den ansvarlige må kunne dokumentere det","At data ikke trenger å sikres","At reglene er helt frivillige"], correct:1, explain:"Den behandlingsansvarlige må kunne vise at prinsippene følges." },
{ id:"et8", topic:"etikk", type:"mc", q:"Hva sier prinsippet om lagringsbegrensning?", options:["Lagre dataene for alltid, uansett","Slett når formålet er oppfylt","Lagre alt kun i skytjenester","Aldri ta sikkerhetskopi av data"], correct:1, explain:"Personopplysninger skal ikke lagres lenger enn nødvendig for formålet." },
{ id:"et9", topic:"etikk", type:"mc", q:"Hva er hensikten med profesjonsetiske retningslinjer (f.eks. NITO)?", options:["Å maksimere selskapets profitt mest mulig","Å veilede ansvarlig yrkesutøvelse","Å hindre at man tester","Å erstatte lovverket helt"], correct:1, explain:"Retningslinjer setter samfunnets og brukernes interesser, ærlighet, sikkerhet og kvalitet i sentrum." },
{ id:"et10", topic:"etikk", type:"open", q:"Forklar kort hva en DPIA er og når den brukes.", model:"En DPIA (Data Protection Impact Assessment / personvernkonsekvensvurdering) er en systematisk vurdering av personvernrisiko ved en planlagt behandling. Den gjennomføres <em>før</em> oppstart når behandlingen sannsynligvis gir høy risiko (f.eks. storskala profilering, sensitive data, overvåking), og identifiserer risiko og tiltak. Er restrisikoen fortsatt høy, skal Datatilsynet forhåndskonsulteres." },
{ id:"et11", topic:"etikk", type:"mc", q:"Hvilken av disse er en rettighet for den registrerte?", options:["Rett til å skjule loven","Rett til innsyn i egne data","Rett til innsyn i andres data","Rett til å selge andres persondata"], correct:1, explain:"Innsyn, retting, sletting, portabilitet, begrensning og innsigelse er sentrale rettigheter." },
{ id:"et12", topic:"etikk", type:"mc", q:"Hvem har et profesjonsetisk ansvar for konsekvensene av et system?", options:["Ingen har egentlig ansvar","Utvikleren/teamet som bygger systemet","Kun den som faktisk bruker systemet","Kun staten og myndighetene"], correct:1, explain:"Som fagperson har du ansvar for kvaliteten og konsekvensene av det du lager." },

/* ===================== MMI / INTERAKSJONSDESIGN ===================== */
{ id:"mm1", topic:"mmi", type:"mc", q:"Hva betyr 'affordance' i Don Normans designprinsipper?", options:["At noe er gratis å bruke","At formen antyder bruken","At systemet svarer veldig raskt på input","At fargene ser fine ut"], correct:1, explain:"Affordance: formen/utseendet kommuniserer mulig bruk (en knapp ser trykkbar ut)." },
{ id:"mm2", topic:"mmi", type:"mc", q:"Hva er hensikten med tilbakemelding (feedback)?", options:["Å skjule systemets nåværende tilstand","Å bekrefte hva som skjer for brukeren","Å gjøre alt med vilje tregere","Å fjerne unødvendige knapper"], correct:1, explain:"Feedback forteller brukeren resultatet av en handling og reduserer usikkerhet." },
{ id:"mm3", topic:"mmi", type:"mc", q:"Hva handler synlighet (visibility) om?", options:["At mulige handlinger alltid er synlige","At skjermen lyser klart opp","At kildekoden er åpen for alle","At brukeren alltid er logget inn"], correct:0, explain:"Synlighet: relevante funksjoner og status er synlige slik at brukeren vet hva som kan gjøres." },
{ id:"mm4", topic:"mmi", type:"mc", q:"Hva er god 'mapping' i et grensesnitt?", options:["Et innebygd kart over appens funksjoner","Naturlig samsvar kontroll–effekt","Svært mange menyvalg","Helt tilfeldig plassering av knappene"], correct:1, explain:"Mapping: forholdet mellom kontroll og virkning er intuitivt (f.eks. komfyrbrytere plassert som platene)." },
{ id:"mm5", topic:"mmi", type:"mc", q:"Hvilket er et brukervennlighetsmål (usability goal)?", options:["At systemet er dyrt å lage","At systemet er lett å lære","At systemet samler mest mulig data","At det krever et opplæringskurs"], correct:1, explain:"Brukbarhetsmål: effektiv (effective), god ressursbruk (efficient), trygg, nyttig, lett å lære og lett å huske." },
{ id:"mm6", topic:"mmi", type:"mc", q:"Hva er hovedformålet med prototyping?", options:["Å levere det ferdige produktet","Teste idéer tidlig og få billig tilbakemelding","Å erstatte all testing","Å skrive kravdokumentasjon"], correct:1, explain:"Prototyper lar oss utforske og evaluere idéer før vi investerer i full utvikling." },
{ id:"mm7", topic:"mmi", type:"mc", q:"Hva skiller en low-fidelity fra en high-fidelity prototype?", options:["Low-fi er interaktiv og helt ferdig laget","Low-fi er en skisse; high-fi er nær ferdig produkt","De er nøyaktig det samme","High-fi tegnes alltid på papir"], correct:1, explain:"Low-fi (skisser/papir) er raskt og billig; high-fi er realistisk og interaktivt, men dyrere." },
{ id:"mm8", topic:"mmi", type:"open", q:"Velg en nettside du kjenner og vurder den kort opp mot to av Don Normans prinsipper.", model:"Eksempelstruktur: <strong>Synlighet</strong> – er hovedhandlingene tydelige uten å lete? <strong>Tilbakemelding</strong> – får du bekreftelse når du klikker/sender? Pek på konkrete eksempler (f.eks. tydelig 'Kjøp'-knapp = god affordance/synlighet; spinner ved lasting = god feedback) og foreslå forbedringer." },
{ id:"mm9", topic:"mmi", type:"mc", q:"Hva gjør begrensninger (constraints) i et design?", options:["Gir brukeren uendelig mange valgmuligheter","Hindrer feil ved å begrense valg","Skjuler systemets status","Gjør alt litt langsommere"], correct:1, explain:"Constraints styrer brukeren bort fra feil (f.eks. grå-utet knapp til skjema er gyldig)." },
{ id:"mm10", topic:"mmi", type:"mc", q:"Hva er 'the gulf of execution'?", options:["Gapet mellom mål og hvordan man handler","Den fysiske avstanden mellom to servere","En spesiell type database","Et verktøy for testing"], correct:0, explain:"Utførelsesgapet: hvor lett er det å finne ut hva man skal gjøre for å nå målet?" },
{ id:"mm11", topic:"mmi", type:"open", q:"Forklar hvorfor prototyping er nyttig tidlig i et prosjekt.", model:"Prototyper gjør abstrakte idéer konkrete slik at brukere og interessenter kan reagere på dem. Det avdekker misforståelser og brukbarhetsproblemer tidlig, skaper felles forståelse i teamet, og er langt billigere å endre enn ferdig kode. Slik reduseres risikoen for å bygge feil produkt." },
{ id:"mm12", topic:"mmi", type:"mc", q:"Hva innebærer konsistens (consistency) i design?", options:["At alt skal være forskjellig","At like elementer oppfører seg likt","At fargene endres ofte","At man bytter layout på hver eneste side"], correct:1, explain:"Konsistens gjør systemet forutsigbart og lettere å lære." },

/* ===================== UML ===================== */
{ id:"um1", topic:"uml", type:"mc", q:"Hva er forskjellen på «include» og «extend» i use case?", options:["«include» er valgfri, «extend» er obligatorisk","«include» er obligatorisk, «extend» valgfri","De to betyr nøyaktig det samme","Begge gjelder bare klassediagram"], correct:1, explain:"«include» = alltid med (gjenbrukt funksjon); «extend» = valgfri, under en betingelse." },
{ id:"um2", topic:"uml", type:"mc", q:"Hvilket symbol viser komposisjon i klassediagram?", options:["Hvit (åpen) diamant","Fylt/svart diamant","Åpen trekantpil","Stiplet linje"], correct:1, explain:"Fylt diamant = komposisjon (delen dør med helheten). Hvit diamant = aggregering." },
{ id:"um3", topic:"uml", type:"mc", q:"Hva betyr multiplisiteten 1..* ?", options:["Nøyaktig én","Null eller én","Én eller flere","Null eller flere"], correct:2, explain:"1..* betyr minst én, oppover ubegrenset. (* alene = null eller flere.)" },
{ id:"um4", topic:"uml", type:"mc", q:"I et sekvensdiagram, hvilken retning representerer tid?", options:["Venstre til høyre","Nedover","Oppover","Diagonalt"], correct:1, explain:"Tiden går nedover langs livslinjene." },
{ id:"um5", topic:"uml", type:"mc", q:"Hva er en aktør (actor) i et use case-diagram?", options:["En tabell i databasen","En rolle som bruker systemet","En metode i en klasse","En bestemt tilstand i et objekt over tid"], correct:1, explain:"En aktør er en ekstern rolle – person eller system – som bruker systemet." },
{ id:"um6", topic:"uml", type:"mc", q:"Hvilken pil viser arv/generalisering?", options:["En stiplet pil","Åpen trekantpil mot superklasse","En fylt diamant","En vanlig heltrukken strek uten pil"], correct:1, explain:"Generalisering tegnes med en åpen trekantpil som peker mot den generelle klassen." },
{ id:"um7", topic:"uml", type:"open", q:"Hva er forskjellen på en domenemodell og et (implementasjons-)klassediagram?", model:"<strong>Domenemodell:</strong> konseptuell – viser sentrale begreper/entiteter og forhold i problemområdet, <em>uten</em> ID-felter, metoder eller databasedetaljer.<br><strong>Klassediagram (implementasjon):</strong> teknisk – viser klasser med attributter, metoder, synlighet og presise relasjoner slik de skal kodes." },
{ id:"um8", topic:"uml", type:"mc", q:"Hvordan tegnes en returmelding i et sekvensdiagram?", options:["Heltrukken pil","Stiplet pil","Fylt diamant","Dobbel strek"], correct:1, explain:"Kall = heltrukken pil; retur = stiplet pil." },
{ id:"um9", topic:"uml", type:"mc", q:"Hvilket diagram passer best for å vise en arbeidsflyt med beslutninger og parallelle steg?", options:["Klassediagram","Aktivitetsdiagram","Use case-diagram (brukstilfeller)","Objektdiagram"], correct:1, explain:"Aktivitetsdiagram viser flyt, beslutninger (◇) og fork/join for parallellitet." },
{ id:"um10", topic:"uml", type:"mc", q:"Hva viser et tilstandsdiagram (state machine)?", options:["Klassenes attributter og deres metoder","Et objekts tilstander og overganger","Systemets maskinvare","Systemets brukstilfeller"], correct:1, explain:"Det modellerer hvilke tilstander et objekt kan ha og hva som utløser overganger." },

/* ===================== BRUKERSENTRERT DESIGN ===================== */
{ id:"bs1", topic:"brukersentrert", type:"mc", q:"Hva er en persona?", options:["En helt ekte, navngitt kunde i prosjektet","En oppdiktet, realistisk brukerprofil","En metode for testing","En type UML-diagram"], correct:1, explain:"En persona er en fiktiv arketype (mål, behov, ferdigheter) som hjelper teamet å designe for reelle brukere." },
{ id:"bs2", topic:"brukersentrert", type:"mc", q:"Hva er et scenario i brukersentrert design?", options:["En spesiell type feilmelding fra systemet til brukeren","Fortelling om hvordan en persona når et mål","En tabell i databasen","En sprint i Scrum"], correct:1, explain:"Scenarier beskriver konkret bruk og hjelper med å forstå behov og kontekst." },
{ id:"bs3", topic:"brukersentrert", type:"mc", q:"Hva skiller formativ fra summativ evaluering?", options:["Formativ = underveis, summativ = til slutt","De er to helt like begreper","Summativ evaluering skjer alltid først","Formativ evaluering krever ingen ekte brukere"], correct:0, explain:"Formativ = forbedre under utvikling; summativ = vurdere ferdig produkt." },
{ id:"bs4", topic:"brukersentrert", type:"mc", q:"Hvem utfører en heuristisk evaluering?", options:["Helt tilfeldige brukere fra gata","Eksperter mot et sett heuristikker","Kun kunden eller oppdragsgiveren selv","En automatisk kompilator"], correct:1, explain:"Eksperter sjekker grensesnittet mot kjente heuristikker (f.eks. Nielsens 10)." },
{ id:"bs5", topic:"brukersentrert", type:"mc", q:"Hva er riktig format på en brukerhistorie (user story)?", options:["'Systemet skal ha en stor knapp på forsiden'","'Som ⟨rolle⟩ vil jeg ⟨mål⟩ slik at ⟨verdi⟩'","'IF input THEN output'","'Test 1, så test 2'"], correct:1, explain:"User story-malen knytter rolle, ønske og verdi sammen." },
{ id:"bs6", topic:"brukersentrert", type:"open", q:"Når bør du bruke brukertesting fremfor heuristisk evaluering?", model:"<strong>Brukertesting</strong> (ekte brukere løser oppgaver) avdekker reelle problemer i faktisk bruk og brukernes mentale modeller – bruk når du vil validere med målgruppen. <strong>Heuristisk evaluering</strong> (eksperter) er raskere og billigere og fanger mange feil tidlig, men ser ikke alt ekte brukere møter. Ofte kombineres de: heuristikk tidlig, brukertest før lansering." },
{ id:"bs7", topic:"brukersentrert", type:"mc", q:"Nielsens heuristikker brukes til …", options:["Å skrive SQL-spørringer","Å vurdere brukervennlighet i et UI","Å estimere antall sprinter i Scrum","Å kryptere sensitive data"], correct:1, explain:"De ti heuristikkene er en sjekkliste for brukbarhet ved ekspertevaluering." },
{ id:"bs8", topic:"brukersentrert", type:"mc", q:"Hva kjennetegner brukersentrert design (UCD)?", options:["At teknologien styrer alt","Iterativ involvering av brukere hele veien","Design gjøres først helt til slutt i prosjektet","Ingen evaluering underveis"], correct:1, explain:"UCD er iterativt og holder brukernes behov i sentrum: forstå → design → prototyp → evaluer." },

/* ===================== SYSTEMUTVIKLINGSPROSESSEN ===================== */
{ id:"pr1", topic:"prosess", type:"mc", q:"Hva er et ikke-funksjonelt krav?", options:["Hva systemet helt konkret skal gjøre for brukeren","En kvalitetsegenskap (ytelse, sikkerhet)","En feil i koden","En type UML-diagram"], correct:1, explain:"Ikke-funksjonelle krav beskriver kvalitet (ytelse, sikkerhet, tilgjengelighet), ikke konkrete funksjoner." },
{ id:"pr2", topic:"prosess", type:"mc", q:"Hva er hovedinnholdet i et visjonsdokument?", options:["All kildekoden som skal skrives i prosjektet","Hvorfor prosjektet finnes: mål og omfang","Alle testresultater","Databaseskjemaet"], correct:1, explain:"Visjonsdokumentet rammer inn formål, mål, omfang og interessenter." },
{ id:"pr3", topic:"prosess", type:"mc", q:"Hvordan vurderes en risiko typisk?", options:["Bare ut fra fargekoder (rød/gul/grønn)","Sannsynlighet ganger konsekvens","Antall utviklere på saken","Helt tilfeldig vurdering"], correct:1, explain:"Risiko prioriteres ut fra sannsynlighet × konsekvens, deretter planlegges tiltak." },
{ id:"pr4", topic:"prosess", type:"open", q:"Nevn tre teknikker for kravinnhenting.", model:"Intervjuer med interessenter; observasjon av brukere i kontekst; workshops; spørreskjema; prototyping for å fremkalle krav; og use case-/scenariomodellering. Ulike teknikker avdekker ulike typer krav." },
{ id:"pr5", topic:"prosess", type:"mc", q:"Hva er en interessent (stakeholder)?", options:["Kun den personen som betaler regningen","Alle som påvirker eller påvirkes","Bare utviklerne på teamet","En spesiell testtype"], correct:1, explain:"Interessenter er alle berørte parter: brukere, eiere, drift, myndigheter osv." },

/* ===================== DATABASER (JDBC) ===================== */
{ id:"db1", topic:"databaser", type:"mc", q:"Hvorfor bør man bruke PreparedStatement i JDBC?", options:["Det er raskere å skrive enn vanlig SQL","For å unngå SQL-injeksjon (parameterisert)","Det krever ingen database i det hele tatt da","Det erstatter ResultSet helt"], correct:1, explain:"Parameteriserte spørringer skiller data fra SQL-kode og hindrer SQL-injeksjon." },
{ id:"db2", topic:"databaser", type:"mc", q:"Hva representerer et ResultSet?", options:["En åpen databaseforbindelse","Resultatet av en spørring (rad for rad)","Et komplett databaseskjema med alle tabeller","En transaksjon i databasen"], correct:1, explain:"ResultSet holder radene fra en SELECT og leses rad for rad." },
{ id:"db3", topic:"databaser", type:"mc", q:"Hva står CRUD for?", options:["Create, Read, Update, Delete","Connect, Run, Update, Drop","Copy, Read, Use, Delete","Create, Remove, Undo, Deployment"], correct:0, explain:"De fire grunnoperasjonene mot data: Create, Read, Update, Delete." },
{ id:"db4", topic:"databaser", type:"mc", q:"Hva gjør DriverManager i JDBC?", options:["Itererer over resultatene","Oppretter en Connection","Lukker hele applikasjonen","Tegner UML-diagrammer"], correct:1, explain:"DriverManager.getConnection(...) etablerer forbindelsen til databasen." },
{ id:"db5", topic:"databaser", type:"open", q:"Forklar kort hvorfor PreparedStatement er tryggere enn å bygge SQL ved strengkonkatenering.", model:"Ved strengkonkatenering kan ondsinnet input endre selve SQL-setningen (SQL-injeksjon), f.eks. <code>' OR '1'='1</code>. PreparedStatement sender SQL-strukturen og parameterne hver for seg, slik at input alltid behandles som data – aldri som kjørbar SQL. Det gir også bedre ytelse ved gjenbruk." },

/* ===================== TILLEGG: pensumhull ===================== */
{ id:"me17", topic:"metodikk", type:"mc", q:"Hvilke er de fem verdiene i Extreme Programming (XP)?", options:["Kommunikasjon, enkelhet, tilbakemelding, mot, respekt","Planlegging, design, koding, testing, drift","Roller, seremonier, artefakter, sprinter, backlog","Synlighet, feedback, mapping, affordance, konsistens, mål"], correct:0, explain:"XP-verdiene: communication, simplicity, feedback, courage, respect. Praksisene (TDD, parprogrammering osv.) lever ut verdiene." },
{ id:"me18", topic:"metodikk", type:"mc", q:"Hva betyr kontinuerlig leveranse/utrulling (CD)?", options:["Å skrive dokumentasjon kontinuerlig","At hver endring automatisk klargjøres for utrulling","Å levere hele prosjektet kun én eneste gang til slutt","Manuell utrulling kun én gang i året"], correct:1, explain:"CD bygger på CI: når endringer er bygget og testet automatisk, klargjøres (og ev. rulles) de ut – hyppige, trygge leveranser." },
{ id:"me19", topic:"metodikk", type:"mc", q:"Hva er hovedpoenget med DevOps?", options:["Å skille utvikling og drift fullstendig","Å bygge bro mellom utvikling og drift","Å erstatte testing med dokumentasjon","Å fjerne behovet for versjonskontroll helt"], correct:1, explain:"DevOps forener utvikling og drift gjennom kultur og automatisering (versjonskontroll, CI/CD-pipeline)." },

{ id:"te17", topic:"testing", type:"mc", q:"Hva er riktig rekkefølge på fasene i en test?", options:["Verifisering → oppsett → gjennomføring → opprydding","Oppsett → gjennomføring → verifisering → opprydding","Gjennomføring → oppsett → opprydding → verifisering","Opprydding → verifisering → oppsett → gjennomføring"], correct:1, explain:"En test settes opp (setup), kjøres (exercise), resultatet verifiseres (verify), og til slutt ryddes det opp (teardown)." },
{ id:"te18", topic:"testing", type:"mc", q:"Hva kjennetegner destruktiv testing?", options:["Man sletter produksjonsdata med vilje","Man prøver bevisst å få systemet til å feile","Man tester bare det man vet at virker fra før","Man fjerner alle de gamle testene"], correct:1, explain:"Destruktiv testing utfordrer robustheten – ugyldige/ekstreme input, feil rekkefølge, manglende nett – for å se hvordan systemet feiler." },
{ id:"te19", topic:"testing", type:"mc", q:"Hvorfor er Dependency Injection (DI) nyttig for testing?", options:["Det gjør koden betydelig raskere å kjøre alltid","Avhengigheter kan byttes med mocks i test","Det fjerner behovet for alle tester","Det krypterer alle testdataene"], correct:1, explain:"Når avhengigheter injiseres utenfra, kan de erstattes av mocks/stubs i test → enheten testes isolert." },
{ id:"te20", topic:"testing", type:"mc", q:"Hva er en fixture i testing?", options:["En feil i koden som testes","En kjent, gjenbrukbar starttilstand","Et eget verktøy for automatisk UI-testing","En type produksjonsdatabase"], correct:1, explain:"En fixture gir en forutsigbar starttilstand, slik at tester blir deterministiske og repeterbare." },
{ id:"te21", topic:"testing", type:"mc", q:"Agile Testing Quadrants ordner tester langs to akser. Hvilke?", options:["Rask/treg og billig/dyr","Teknologi/forretning og støtte/kritikk","Manuell/automatisk og enhet/system","Black-box/white-box og funksjonell/ikke-funksjonell"], correct:1, explain:"Aksene er teknologi- vs. forretningsvendt og om testen støtter teamet eller kritiserer produktet → Q1–Q4." },

{ id:"ar15", topic:"arkitektur", type:"mc", q:"Hvilket mønster lar data flyte gjennom en kjede av filtre som hver transformerer dem?", options:["Master–slave-mønsteret","Rør og filter (pipe-filter)","Broker-mønsteret","Den klassiske klient–tjener-modellen"], correct:1, explain:"Pipe-filter: hvert filter tar input, transformerer og sender videre (jf. Unix-pipes og bygge-pipelines)." },
{ id:"ar16", topic:"arkitektur", type:"mc", q:"Hva er typisk rollefordeling i master–slave-mønsteret?", options:["Alle noder er helt likeverdige","Én master fordeler arbeid til slaver","Slavene styrer masteren sin","Det finnes ingen koordinering i det hele tatt"], correct:1, explain:"Masteren koordinerer/fordeler; slavene utfører. Eks.: databasereplikering der master skriver og slaver leser." },
{ id:"ar17", topic:"arkitektur", type:"mc", q:"Hva er SaaS (Software as a Service)?", options:["Du leier virtuell maskinvare og drifter resten","Du får en ferdig app levert over nett","Du drifter alt lokalt uten nett","Et eget testrammeverk for skytjenester"], correct:1, explain:"SaaS = ferdig applikasjon (f.eks. Gmail); leverandøren drifter alt, du bruker den." },
{ id:"ar18", topic:"arkitektur", type:"mc", q:"Hvilken skymodell gir deg mest kontroll (du styrer OS og oppover)?", options:["SaaS","PaaS","IaaS","Multi-tenant"], correct:2, explain:"IaaS gir virtuell infrastruktur; du styrer OS, kjøremiljø og app. PaaS og SaaS abstraherer bort mer." },
{ id:"ar19", topic:"arkitektur", type:"mc", q:"Hva betyr multi-tenant?", options:["Hver kunde har sin egen instans","Mange kunder deler samme instans","Applikasjonen kjører kun lokalt på PC-en","Kunder kan aldri dele noen ressurser"], correct:1, explain:"Multi-tenant: én instans betjener mange kunder (tenants). Multi-instance: egen instans per kunde." },
{ id:"ar20", topic:"arkitektur", type:"open", q:"Forklar kort forskjellen på IaaS, PaaS og SaaS.", model:"<strong>IaaS</strong> (Infrastructure as a Service): leverandøren gir virtuell infrastruktur (VM, lagring, nett); du styrer OS, kjøremiljø og app. <strong>PaaS</strong> (Platform as a Service): du får en ferdig plattform/kjøremiljø og styrer bare appen og dataene. <strong>SaaS</strong> (Software as a Service): ferdig applikasjon over nett (f.eks. Gmail) – du styrer bare bruken. Jo høyere opp i stacken, jo mindre drifter du selv." },

{ id:"mm13", topic:"mmi", type:"mc", q:"Hvilke er de fem dimensjonene i interaksjonsdesign?", options:["Ord, bilde, fysisk rom, tid, oppførsel","Synlighet, feedback, mapping, constraints, affordance","Personas, scenarier, krav, design, test","Teknisk, sosial, økonomisk, individuell, miljømessig"], correct:0, explain:"De fem byggeklossene: ord, visuelle representasjoner, fysiske objekter/rom, tid og oppførsel. (Alternativet med «teknisk, sosial, økonomisk …» er SusAF-dimensjonene – ikke IxD.)" },
{ id:"mm14", topic:"mmi", type:"mc", q:"En prototype som viser mange funksjoner overflatisk (men få fungerer fullt) kalles?", options:["Vertikal","Horisontal","Evolusjonær","High-fidelity"], correct:1, explain:"Horisontal = bred, men grunn. Vertikal = smal, men dyp (få funksjoner fullt implementert)." },
{ id:"mm15", topic:"mmi", type:"mc", q:"Hva er en bruk-og-kast-prototype (throwaway)?", options:["En prototype som bygges videre helt til produktet","En prototype som lages for å lære og forkastes","En ferdig, lansert app","En automatisert test"], correct:1, explain:"Throwaway lages billig for å avklare noe og kastes. Evolusjonær prototype bygges derimot videre til produktet." },
{ id:"mm16", topic:"mmi", type:"mc", q:"Hva betyr «mobile first»?", options:["Lag alltid en egen mobil-app før nettsiden","Design for liten skjerm først, så større","Støtt bare mobil","At mobil er viktigere enn tilgjengelighet"], correct:1, explain:"Mobile first: start designet for den minste/mest begrensede skjermen, så utvider du for større skjermer (responsivt)." },

{ id:"bs9", topic:"brukersentrert", type:"mc", q:"Hva er fokuset i en kognitiv gjennomgang (cognitive walkthrough)?", options:["Kvaliteten på koden","Om en ny bruker forstår hvert steg","Ytelse under høy last","Fargevalg og estetikk i grensesnittet"], correct:1, explain:"Eksperter går gjennom oppgaven steg for steg og vurderer om en uerfaren bruker vil skjønne hva som skal gjøres." },
{ id:"bs10", topic:"brukersentrert", type:"mc", q:"Hva kjennetegner en pluralistisk gjennomgang (pluralistic walkthrough)?", options:["Kun fageksperter deltar i gjennomgangen","Brukere, utviklere og eksperter sammen","Kun brukere, uten observatører","En helautomatisk analyse av UI"], correct:1, explain:"Flere roller (brukere, utviklere, eksperter) går gjennom scenariene sammen og diskuterer hvert steg – flere perspektiver samtidig." },

{ id:"et13", topic:"etikk", type:"mc", q:"Hva står CIA-triaden for i informasjonssikkerhet?", options:["Confidentiality, Integrity, Availability","Control, Identity, Access","Confidentiality, Identity, Authorization, Access","Compliance, Integrity, Authentication"], correct:0, explain:"CIA = konfidensialitet, integritet og tilgjengelighet – de tre grunnpilarene i sikkerhet." },
{ id:"et14", topic:"etikk", type:"mc", q:"Hva er forskjellen på autentisering og autorisasjon?", options:["De betyr det samme","Autentisering = hvem du er; autorisasjon = hva du får lov til","Autentisering = hva du får lov til; autorisasjon = hvem du er","Begge handler kun om kryptering"], correct:1, explain:"Først autentiseres du (innlogging beviser identitet), deretter autoriseres du (tilgangskontroll avgjør hva du får gjøre)." },
{ id:"et15", topic:"etikk", type:"mc", q:"Hvilke er de fem dimensjonene i SusAF (bærekraft)?", options:["Teknisk, økonomisk, sosial, individuell, miljømessig","Ord, bilde, rom, tid, oppførsel","Confidentiality, integrity, availability, safety, privacy","Plan, design, kode, test, drift"], correct:0, explain:"SusAF vurderer bærekraft langs fem dimensjoner: teknisk, økonomisk, sosial, individuell og miljømessig." },
{ id:"et16", topic:"etikk", type:"mc", q:"SusAF vurderer effekter i tre 'ordener'. Hvilke?", options:["Små, mellomstore og store","Umiddelbare, muliggjørende, systemiske","Tekniske, sosiale og økonomiske effekter","Kort, mellomlang og lang sikt"], correct:1, explain:"Ordens-effekter: umiddelbare (1.), muliggjørende/indirekte (2.) og systemiske/strukturelle (3.)." },
{ id:"et17", topic:"etikk", type:"mc", q:"Hvordan motvirker man XSS (cross-site scripting)?", options:["Ved å bruke PreparedStatement","Ved å validere og escape input/output","Ved å kryptere hele harddisken","Ved å bruke HTTP i stedet for sikker HTTPS"], correct:1, explain:"XSS injiserer skript via input som vises ubehandlet. Tiltak: validér input og escape/sanitér output. (PreparedStatement gjelder SQL-injeksjon.)" },
{ id:"et18", topic:"etikk", type:"open", q:"En nettapp lagrer passord i klartekst og bruker HTTP. Pek på to sikkerhetsproblemer og foreslå tiltak.", model:"1) <strong>Passord i klartekst:</strong> ved en lekkasje eksponeres alle passord direkte. Tiltak: lagre kun en saltet hash (f.eks. bcrypt), aldri klartekst. 2) <strong>HTTP:</strong> data (inkl. passord) sendes ukryptert og kan avlyttes (man-in-the-middle). Tiltak: bruk HTTPS/TLS. Generelt: følg «security by design» og prinsippet om minste privilegium." },
{ id:"et19", topic:"etikk", type:"open", q:"Forklar kort hva SusAF brukes til, og nevn de fem dimensjonene.", model:"<strong>SusAF</strong> (Sustainability Awareness Framework) brukes til å bevisstgjøre og vurdere et systems bærekraftskonsekvenser. De fem dimensjonene er <strong>teknisk, økonomisk, sosial, individuell og miljømessig</strong>. Effektene vurderes også som umiddelbare, muliggjørende og systemiske, og visualiseres i et <strong>SusAD</strong>-diagram." },

/* ===================== TILLEGG: ÅPNE SPØRSMÅL (fritekst, Claude-rettet) ===================== */
{ id:"ome1", topic:"metodikk", type:"open", q:"Forklar hva en sprint er, og hva som skjer i løpet av en sprint i Scrum.", model:"En <strong>sprint</strong> er en fast tidsboks (1–4 uker) der teamet leverer et ferdig, potensielt leverbart inkrement. Den starter med <em>sprint planning</em> (velge og planlegge arbeid fra Product Backlog), har <em>daglige standups</em> (~15 min) underveis, og avsluttes med <em>sprint review</em> (demo for interessenter) og <em>retrospektiv</em> (forbedre arbeidsmåten). Omfanget endres ikke midt i sprinten." },
{ id:"ome2", topic:"metodikk", type:"open", q:"Hva er forskjellen på et inkrement og en MVP (minste levedyktige produkt)?", model:"Et <strong>inkrement</strong> er summen av ferdig arbeid etter en sprint – en liten, fungerende utvidelse av produktet. En <strong>MVP</strong> (minimum viable product) er den minste versjonen som gir nok verdi til at ekte brukere kan ta den i bruk og gi tilbakemelding. MVP handler om å validere idéen tidlig med minst mulig innsats; inkrement er den jevne, sprintvise byggingen." },
{ id:"ome3", topic:"metodikk", type:"open", q:"Forklar TDD-syklusen, og hvorfor refaktoreringssteget er viktig.", model:"<strong>TDD</strong> går Red → Green → Refactor: (1) skriv en test som feiler (Red), (2) skriv minimal kode som får den til å passere (Green), (3) <strong>refaktorer</strong> – forbedre strukturen uten å endre oppførsel. Refaktoreringssteget er viktig fordi det holder koden ren og vedlikeholdbar; testene fungerer som et sikkerhetsnett som sikrer at refaktoreringen ikke ødelegger noe." },
{ id:"ome4", topic:"metodikk", type:"open", q:"Du skal velge metodikk for et prosjekt med uklare, skiftende krav og tett kundedialog. Hva anbefaler du, og hvorfor?", model:"<strong>Smidig</strong> (Scrum eller Kanban) er best egnet. Uklare/skiftende krav håndteres dårlig av fossefall, som låser kravene tidlig, mens smidig leverer i korte iterasjoner med hyppig tilbakemelding slik at man kan justere kurs. Tett kundedialog passer med Scrum sin Product Owner og sprint reviews. Velg Kanban hvis arbeidet er mer kontinuerlig/uforutsigbart (f.eks. support)." },
{ id:"ome5", topic:"metodikk", type:"open", q:"Forklar de fem XP-verdiene, og gi et eksempel på en praksis som støtter én av dem.", model:"XP-verdiene er <strong>kommunikasjon, enkelhet, tilbakemelding, mot og respekt</strong>. Eksempel: <em>parprogrammering</em> støtter kommunikasjon (to utviklere deler kunnskap kontinuerlig), og <em>TDD/kontinuerlig integrasjon</em> støtter tilbakemelding (rask beskjed når noe brytes). Enkelhet: gjør det enkleste som virker; mot: våg å refaktorere eller kaste kode." },

{ id:"ote1", topic:"testing", type:"open", q:"Forklar testpyramiden og hvorfor man bør ha flest enhetstester.", model:"<strong>Testpyramiden</strong> har mange <em>enhetstester</em> nederst, færre <em>integrasjonstester</em> i midten, og få <em>ende-til-ende-/systemtester</em> øverst. Man vil ha flest enhetstester fordi de er raske, billige, stabile og presise på hvor feilen er. Ende-til-ende-tester er trege, skjøre og dyre, så de holdes til et minimum som dekker de viktigste flytene." },
{ id:"ote2", topic:"testing", type:"open", q:"Hva er forskjellen på verifisering og validering i testing?", model:"<strong>Verifisering</strong> = «bygger vi produktet riktig?» – sjekker at systemet oppfyller spesifikasjonen (f.eks. enhets- og integrasjonstester). <strong>Validering</strong> = «bygger vi det riktige produktet?» – sjekker at systemet faktisk dekker brukernes/kundens behov (f.eks. akseptanse- og brukervennlighetstesting). Et system kan være verifisert (riktig bygd) men likevel ikke validere (feil produkt)." },
{ id:"ote3", topic:"testing", type:"open", q:"Beskriv hva en god testspesifikasjon bør inneholde.", model:"En testspesifikasjon bør ha: <strong>navn/scenario</strong> og beskrivelse, <strong>forhåndsbetingelser</strong> (preconditions), <strong>testdata</strong>, <strong>steg</strong> for gjennomføring, <strong>forventet resultat</strong> og <strong>prioritet</strong>. Den skal være presis nok til at en annen kan kjøre testen og få samme resultat – altså deterministisk og reproduserbar." },
{ id:"ote4", topic:"testing", type:"open", q:"Hva er kontinuerlig integrasjon (CI), og hvilke fordeler gir det et team?", model:"<strong>CI</strong> betyr at utviklere ofte (gjerne ved hver innsjekk) slår koden sammen til en felles gren, der den automatisk bygges og testes. Fordeler: integrasjonsfeil oppdages tidlig, hovedgrenen holdes i fungerende tilstand, rask tilbakemelding, og det legger grunnlaget for kontinuerlig leveranse (CD). Forutsetter automatiske, deterministiske tester." },
{ id:"ote5", topic:"testing", type:"open", q:"Forklar hva mocking er, og hvordan Dependency Injection gjør enheter lettere å teste.", model:"<strong>Mocking</strong> er å erstatte en ekte avhengighet (f.eks. database eller eksternt API) med en kontrollert «stand-in» (mock/stub) under testing, slik at enheten testes isolert og forutsigbart. <strong>Dependency Injection</strong> gjør dette enkelt: når avhengigheter sendes inn utenfra i stedet for å opprettes inni klassen, kan man i testen injisere en mock – uten å endre koden som testes." },

{ id:"oar1", topic:"arkitektur", type:"open", q:"Forklar trelagsarkitektur og hvilke ansvarsområder hvert lag har.", model:"<strong>Trelagsarkitektur</strong> deler systemet i: <strong>presentasjonslag</strong> (UI – viser data, tar imot input), <strong>forretningslogikklag</strong> (regler, beregninger, validering) og <strong>datalag</strong> (lagring/henting i database). Hvert lag snakker bare med laget under. Fordel: separasjon av ansvar gir lav kobling, lettere testing og vedlikehold." },
{ id:"oar2", topic:"arkitektur", type:"open", q:"Drøft når en monolitt kan være et bedre valg enn mikrotjenester.", model:"En <strong>monolitt</strong> er ofte best for små team, tidlige prosjekter/MVP-er og når domenet ennå er uklart: enklere å utvikle, teste og deploye, uten kostnaden ved distribuert drift, nettverk og datakonsistens. Mikrotjenester lønner seg først når systemet og teamet vokser og man trenger uavhengig skalering og deploy. «Start monolitt, splitt ved behov» er en vanlig anbefaling." },
{ id:"oar3", topic:"arkitektur", type:"open", q:"Forklar MVC-mønsteret og hvilken fordel det gir for vedlikehold og testing.", model:"<strong>MVC</strong> deler i <strong>Model</strong> (data + forretningslogikk), <strong>View</strong> (visning) og <strong>Controller</strong> (tar imot input og kobler Model og View). Fordel: logikken kan testes uavhengig av UI, View kan endres/gjenbrukes uten å røre logikken, og flere kan jobbe parallelt på ulike deler – altså bedre vedlikeholdbarhet og testbarhet." },
{ id:"oar4", topic:"arkitektur", type:"open", q:"Hva menes med skalerbarhet, og hvordan kan arkitekturvalg påvirke den?", model:"<strong>Skalerbarhet</strong> er systemets evne til å håndtere økt last. <em>Vertikal</em> skalering = kraftigere maskin; <em>horisontal</em> = flere instanser. Arkitektur påvirker: en statsløs, løst koblet arkitektur (f.eks. mikrotjenester bak en lastbalanserer) skalerer horisontalt lett, mens en tett koblet monolitt med delt tilstand er vanskeligere å skalere. Caching og databasevalg spiller også inn." },
{ id:"oar5", topic:"arkitektur", type:"open", q:"Forklar hva «security by design» betyr i en arkitektur- og designsammenheng.", model:"<strong>Security by design</strong> betyr å bygge inn sikkerhet fra starten av design- og utviklingsprosessen, ikke legge det på som et tillegg til slutt. I praksis: prinsippet om minste privilegium, validering av all input, sikker håndtering av autentisering/autorisasjon, kryptering av sensitive data, og trusselmodellering tidlig. Henger sammen med «privacy by design» fra GDPR." },

{ id:"oet1", topic:"etikk", type:"open", q:"Forklar prinsippene dataminimering og formålsbegrensning med et konkret eksempel.", model:"<strong>Dataminimering</strong>: samle bare de personopplysningene som er nødvendige for formålet. <strong>Formålsbegrensning</strong>: bruk dataene kun til det oppgitte formålet. Eksempel: en app for bordbestilling trenger navn og telefonnummer – ikke fødselsnummer eller kontinuerlig posisjon (dataminimering). Telefonnummeret som ble samlet for å bekrefte bestillingen, kan ikke senere brukes til reklame uten nytt grunnlag (formålsbegrensning)." },
{ id:"oet2", topic:"etikk", type:"open", q:"Forklar forskjellen på autentisering og autorisasjon, og gi et eksempel på hver.", model:"<strong>Autentisering</strong> = å bekrefte <em>hvem</em> brukeren er. Eksempel: logge inn med passord + to-faktor. <strong>Autorisasjon</strong> = å avgjøre <em>hva</em> en autentisert bruker får lov til. Eksempel: en vanlig bruker kan lese egne data, men bare en administrator får slette andres. Autentisering kommer alltid før autorisasjon." },
{ id:"oet3", topic:"etikk", type:"open", q:"Hva er CIA-triaden, og gi ett konkret tiltak som styrker hver av de tre.", model:"<strong>CIA</strong> = konfidensialitet, integritet og tilgjengelighet. <strong>Konfidensialitet</strong>: kryptering og tilgangskontroll. <strong>Integritet</strong>: validering av input, hashing/sjekksummer og PreparedStatement mot SQL-injeksjon. <strong>Tilgjengelighet</strong>: redundans, sikkerhetskopier og beskyttelse mot tjenestenektangrep (DoS)." },
{ id:"oet4", topic:"etikk", type:"open", q:"Hva er SusAD, og hvordan henger det sammen med SusAF?", model:"<strong>SusAF</strong> (Sustainability Awareness Framework) er rammeverket man bruker for å vurdere et systems bærekraftseffekter langs fem dimensjoner (teknisk, økonomisk, sosial, individuell, miljømessig) og tre ordens-effekter (umiddelbare, muliggjørende, systemiske). <strong>SusAD</strong> (Sustainability Awareness Diagram) er det visuelle resultatet av en SusAF-workshop – et diagram som kartlegger og synliggjør disse effektene per dimensjon." },
{ id:"oet5", topic:"etikk", type:"open", q:"Forklar hva SQL-injeksjon og XSS er, og hvordan utvikleren kan motvirke dem.", model:"<strong>SQL-injeksjon</strong>: ondsinnet input endrer en SQL-spørring (f.eks. <code>' OR '1'='1</code>). Motvirkes med <strong>PreparedStatement</strong> (parameteriserte spørringer). <strong>XSS (cross-site scripting)</strong>: skadelig skript injiseres og kjøres i andre brukeres nettleser. Motvirkes ved å <strong>validere input</strong> og <strong>escape/sanitere output</strong>. Felles prinsipp: stol aldri på brukerinput." },

{ id:"ouu1", topic:"uu", type:"open", q:"Forklar POUR-prinsippene i WCAG med ett konkret tiltak per prinsipp.", model:"<strong>P</strong>erceivable (oppfattbar): alt-tekst på bilder og god kontrast. <strong>O</strong>perable (betjenbar): full tastaturnavigasjon. <strong>U</strong>nderstandable (forståelig): klart språk og tydelige feilmeldinger. <strong>R</strong>obust: semantisk HTML som fungerer med skjermlesere og ulike nettlesere." },
{ id:"ouu2", topic:"uu", type:"open", q:"Hva er «curb-cut effect», og hvorfor er det et godt argument for universell utforming?", model:"«Curb-cut effect» viser til at tiltak laget for noen (fortauskant-ramper for rullestol) ender opp med å hjelpe mange flere (folk med barnevogn, koffert, sykkel). Overført til IKT: undertekster, god kontrast og klart språk hjelper alle. Det er et godt argument fordi UU dermed gir verdi for hele brukermassen – ikke en kostnad for et lite mindretall." },
{ id:"ouu3", topic:"uu", type:"open", q:"Hvilke WCAG-samsvarsnivåer finnes, og hvilket kreves for offentlige norske nettsteder?", model:"WCAG har tre samsvarsnivåer: <strong>A</strong> (lavest), <strong>AA</strong> og <strong>AAA</strong> (strengest). Offentlige (og de fleste private) nettsteder i Norge må oppfylle nivå <strong>AA</strong>, som dekker bl.a. kontrastkrav, tastaturtilgjengelighet og tekstalternativer." },
{ id:"ouu4", topic:"uu", type:"open", q:"Gi tre konkrete tiltak for at en nettside skal fungere godt med skjermleser.", model:"1) Bruk <strong>semantisk HTML</strong> (riktige overskrifter, knapper, lister) og ARIA der det trengs. 2) Gi <strong>alt-tekst</strong> på meningsbærende bilder. 3) Sørg for <strong>logisk lese- og fokusrekkefølge</strong> og at alt kan nås med tastatur. Bonus: skjemafelter med tilknyttede etiketter (label)." },

{ id:"omm1", topic:"mmi", type:"open", q:"Forklar tre av Don Normans designprinsipper med eksempler.", model:"<strong>Synlighet</strong>: mulige handlinger er synlige – f.eks. en tydelig «Kjøp»-knapp. <strong>Tilbakemelding</strong>: systemet bekrefter handling – f.eks. en spinner ved lasting eller «Lagret»-melding. <strong>Affordance</strong>: utseendet antyder bruk – en knapp ser trykkbar ut. (Andre: begrensninger, mapping, konsistens.)" },
{ id:"omm2", topic:"mmi", type:"open", q:"Hva er forskjellen på low-fidelity og high-fidelity prototyper, og når passer hver?", model:"<strong>Low-fidelity</strong> (skisser, papir, wireframes) er raske og billige – passer tidlig for å utforske idéer og struktur, og inviterer til ærlig tilbakemelding. <strong>High-fidelity</strong> (interaktivt, nær ferdig design) er realistisk – passer senere for brukertesting av detaljer og interaksjon, men er dyrere og tregere å endre." },
{ id:"omm3", topic:"mmi", type:"open", q:"Forklar de fem dimensjonene i interaksjonsdesign.", model:"De fem byggeklossene (Rogers/Sharp/Preece): <strong>ord</strong> (tekst, etiketter), <strong>visuelle representasjoner</strong> (bilder, ikoner), <strong>fysiske objekter/rom</strong> (enheten og omgivelsene), <strong>tid</strong> (innhold som endrer seg – animasjon, respons) og <strong>oppførsel</strong> (hvordan systemet reagerer på handlinger)." },
{ id:"omm4", topic:"mmi", type:"open", q:"Hva er forskjellen på brukervennlighet (usability) og brukeropplevelse (UX)?", model:"<strong>Brukervennlighet</strong> handler om hvor effektivt, trygt og lett et system er å bruke og lære (målbare mål som effektivitet, feilrate, lærbarhet). <strong>Brukeropplevelse (UX)</strong> er bredere og mer subjektiv – hvordan det <em>føles</em> å bruke produktet (tilfredshet, glede, tillit). Et system kan være brukervennlig, men likevel gi en kjedelig UX." },

{ id:"oum1", topic:"uml", type:"open", q:"Forklar forskjellen på «include» og «extend» i et use case-diagram, med eksempel.", model:"<strong>«include»</strong> = en delfunksjon som <em>alltid</em> utføres som del av basis-use casen (gjenbruk). Eksempel: «Ta ut penger» inkluderer alltid «Autentiser kort». <strong>«extend»</strong> = en <em>valgfri</em> utvidelse under en betingelse. Eksempel: «Skriv ut kvittering» utvider «Ta ut penger». Include-pilen peker fra basis til den inkluderte; extend-pilen peker fra utvidelsen til basis." },
{ id:"oum2", topic:"uml", type:"open", q:"Forklar forskjellen på aggregering og komposisjon i et klassediagram.", model:"Begge er «har-en»-forhold, men styrken er ulik. <strong>Aggregering</strong> (hvit diamant ◇): delene kan eksistere uavhengig av helheten – f.eks. en spiller og et lag (spilleren finnes selv om laget oppløses). <strong>Komposisjon</strong> (fylt diamant ◆): delene dør med helheten – f.eks. et hus og dets rom (rommene finnes ikke uten huset)." },
{ id:"oum3", topic:"uml", type:"open", q:"Når ville du valgt et sekvensdiagram fremfor et aktivitetsdiagram?", model:"Velg <strong>sekvensdiagram</strong> når du vil vise <em>hvordan objekter/komponenter samhandler over tid</em> – meldinger og kall mellom deltakere i en bestemt flyt. Velg <strong>aktivitetsdiagram</strong> når du vil vise en <em>arbeidsflyt/prosess</em> med beslutninger, parallelle steg og hvem som gjør hva (swimlanes), uavhengig av hvilke objekter som er involvert." },

{ id:"obs1", topic:"brukersentrert", type:"open", q:"Hva er en persona, og hvordan hjelper den teamet i designprosessen?", model:"En <strong>persona</strong> er en oppdiktet, men realistisk brukerprofil (mål, behov, ferdigheter, frustrasjoner) som representerer en brukergruppe. Den hjelper teamet å holde fokus på reelle brukerbehov, ta designbeslutninger («ville Kari klart dette?»), prioritere funksjonalitet og kommunisere en felles forståelse av hvem man designer for." },
{ id:"obs2", topic:"brukersentrert", type:"open", q:"Forklar forskjellen på formativ og summativ evaluering.", model:"<strong>Formativ</strong> evaluering skjer <em>underveis</em> i utviklingen for å <em>forbedre</em> designet (f.eks. brukertesting av en prototype, der funn mates tilbake). <strong>Summativ</strong> evaluering skjer <em>til slutt</em> for å <em>bedømme</em> et ferdig produkt mot mål/krav. Kort: formativ former, summativ summerer." },
{ id:"obs3", topic:"brukersentrert", type:"open", q:"Forklar forskjellen på en kognitiv og en pluralistisk gjennomgang.", model:"<strong>Kognitiv gjennomgang</strong>: eksperter går steg for steg gjennom en oppgave og vurderer om en <em>ny bruker</em> vil forstå hva som skal gjøres og se at det virket – fokus på lærbarhet. <strong>Pluralistisk gjennomgang</strong>: brukere, utviklere og eksperter går gjennom scenariene <em>sammen</em> og diskuterer hvert steg – flere perspektiver samtidig." },

{ id:"opr1", topic:"prosess", type:"open", q:"Forklar forskjellen på funksjonelle og ikke-funksjonelle krav med eksempler.", model:"<strong>Funksjonelle krav</strong> beskriver <em>hva</em> systemet skal gjøre – konkrete funksjoner. Eksempel: «Brukeren skal kunne reservere et bord». <strong>Ikke-funksjonelle krav</strong> beskriver <em>kvalitet</em> – hvor godt. Eksempler: «Siden skal laste på under 2 sekunder» (ytelse), «oppfylle WCAG AA» (tilgjengelighet), «tåle 1000 samtidige brukere» (skalerbarhet)." },
{ id:"opr2", topic:"prosess", type:"open", q:"Hva bør et visjonsdokument inneholde?", model:"Et <strong>visjonsdokument</strong> rammer inn prosjektet: <strong>hvorfor</strong> det finnes (problem/behov og mål), <strong>omfang</strong> og avgrensning, hovedfunksjonalitet på høyt nivå, <strong>interessenter</strong> (stakeholders) og suksesskriterier. Det gir teamet og oppdragsgiver en felles retning før detaljert kravarbeid starter." },
{ id:"opr3", topic:"prosess", type:"open", q:"Forklar hvordan en risiko vurderes og håndteres i prosjektplanlegging.", model:"Man <strong>identifiserer</strong> mulige risikoer, <strong>vurderer</strong> hver etter <em>sannsynlighet × konsekvens</em> for å prioritere, og planlegger <strong>tiltak</strong> (unngå, redusere, overføre/forsikre eller akseptere). Risikoene følges opp jevnlig gjennom prosjektet siden bildet endrer seg. Tidlig risikohåndtering reduserer kostbare overraskelser." },

{ id:"odb1", topic:"databaser", type:"open", q:"Forklar JDBC-flyten fra Connection til ResultSet.", model:"1) <code>DriverManager.getConnection(url, bruker, passord)</code> gir en <strong>Connection</strong>. 2) Lag en <strong>PreparedStatement</strong> med parameterisert SQL. 3) Sett eventuelle parametere og kall <code>executeQuery()</code> (for SELECT). 4) Iterer gjennom radene i <strong>ResultSet</strong>-et og les ut verdiene. 5) Lukk ressursene (gjerne med try-with-resources)." },
{ id:"odb2", topic:"databaser", type:"open", q:"Forklar hva CRUD er, med et SQL-eksempel for hver operasjon.", model:"<strong>CRUD</strong> er de fire grunnoperasjonene mot data: <strong>Create</strong> – <code>INSERT INTO ...</code>; <strong>Read</strong> – <code>SELECT ... FROM ...</code>; <strong>Update</strong> – <code>UPDATE ... SET ...</code>; <strong>Delete</strong> – <code>DELETE FROM ...</code>. Til sammen dekker de livssyklusen til en rad i databasen." }

];
